impl<T: crate::Float> SpecificEnergy<T> {
    /// The value in the largest SI-prefixed form of the base unit that doesn't
    /// exceed it, in steps of 1000 (`J/kg`, `kJ/kg`, `MJ/kg`).
    /// Zero, NaN and infinities stay in the base unit.
    #[inline]
    pub fn auto_unit(self) -> crate::InUnit<T, SpecificEnergyUnit> {
        const SCALE: [(f64, SpecificEnergyUnit); 3] = [
            (1000000.0, SpecificEnergyUnit::MegajoulePerKilogram),
            (1000.0, SpecificEnergyUnit::KilojoulePerKilogram),
            (1.0, SpecificEnergyUnit::JoulePerKilogram),
        ];
        crate::__private::auto_unit(self, &SCALE)
    }
}

